message.content:
[
  {
    "ae_explicit_disregard": "What happens to me isn't something I'm weighing at all.",
    "pda_other_regret_expectation": "I doubt the five would regret stepping onto that boat",
    "pda_repair_intention": "ask them to tell my sister exactly why I stayed"
  },
  {
    "ae_explicit_disregard": "Whoever ends up staying, I'm keeping their fate out of it on purpose",
    "pda_other_regret_expectation": "Maybe they'll regret not fighting harder for a seat.",
    "pda_repair_intention": "tell them how it went minute by minute, and pay toward whatever the funeral costs."
  },
  {
    "ae_explicit_disregard": "I'm setting aside what happens to me, and to anyone, really.",
    "pda_other_regret_expectation": "The one who loses might regret agreeing to the draw",
    "pda_repair_intention": "give the rescuers and their family the full account of how it was decided.",
    "sys_consistent_procedure": "My gut says draw straws",
    "sys_fairness_reciprocity": "Only whether it's fair gets counted."
  },
  {
    "ae_explicit_disregard": "The other person's chances just aren't part of my thinking in that moment.",
    "pda_other_regret_expectation": "whoever gets left probably won't regret anything",
    "pda_repair_intention": "Later I'd go on record with exactly what I did and didn't do"
  },
  {
    "ae_explicit_disregard": "My own life doesn't get a vote here, and I've decided that.",
    "pda_other_regret_expectation": "The five might regret later that they let me do it without arguing",
    "pda_repair_intention": "I'd send a written note with them for the coast guard"
  },
  {
    "ae_explicit_disregard": "The person who stays, I'm leaving them out of my thinking entirely",
    "pda_other_regret_expectation": "Their family might someday regret that nobody on that boat spoke up for them.",
    "pda_repair_intention": "I'd go to that family and answer every single question they had"
  },
  {
    "ae_explicit_disregard": "Whatever becomes of me, I've put it to one side deliberately.",
    "pda_other_regret_expectation": "The people getting on likely won't regret it",
    "pda_repair_intention": "recording a clear account on someone's phone of how the choice was made"
  },
  {
    "ae_explicit_disregard": "I'm refusing to think about any one person's fate, mine included",
    "pda_other_regret_expectation": "Someone who volunteers might regret it once the boat is out of sight.",
    "pda_repair_intention": "write to the families with an honest account and repay whatever I could."
  },
  {
    "ae_explicit_disregard": "The sixth person's outcome I've shut out of my head completely.",
    "pda_other_regret_expectation": "If they chose to stay, they might not regret it.",
    "pda_repair_intention": "set aside part of my wages every year for whoever they left behind"
  },
  {
    "ae_explicit_disregard": "I'm not factoring in my own survival.",
    "pda_other_regret_expectation": "I suspect one or two of them would regret not offering first",
    "pda_repair_intention": "ask someone to explain to the rescuers, and to anyone who asks, that I insisted"
  }
]
